def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == " ":
            if len(text[i:]) > 2 and text[i+1] == " ":
                result.append("-")
                i += 2
            else:
                result.append("_")
                i += 1
        else:
            result.append(text[i])
            i += 1
    return "".join(result) 
